SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRANSACTION;
DECLARE @Run nvarchar(50)=N'MEMO-20261004-C111';
DECLARE @Company bigint=(SELECT TOP 1 CompanyID FROM dbo.TDADUser WHERE Username=N'c111' AND IsActive=1);
DECLARE @User bigint=(SELECT TOP 1 UserID FROM dbo.TDADUser WHERE Username=N'c111' AND CompanyID=@Company AND IsActive=1);
DECLARE @Approver bigint=(SELECT TOP 1 UserID FROM dbo.TDADUser WHERE CompanyID=@Company AND IsActive=1 AND UserID<>@User ORDER BY UserID);
DECLARE @Project bigint=(SELECT ProjectID FROM dbo.TDADProject WHERE ProjectCode=N'LAOO_MEMO' AND IsActive=1);
DECLARE @Partner bigint=(SELECT PartnerID FROM dbo.TDSTCompanySetUp WHERE CompanyID=@Company AND IsActive=1);
DECLARE @Department bigint=(SELECT TOP 1 e.DepartmentOrgUnitID FROM dbo.TDADUserEmployee ue JOIN dbo.TDADEmployee e ON e.CompanyID=ue.CompanyID AND e.EmployeeID=ue.EmployeeID WHERE ue.CompanyID=@Company AND ue.UserID=@User AND ue.IsActive=1 AND e.IsActive=1);
IF @Company IS NULL OR @User IS NULL OR @Approver IS NULL OR @Project IS NULL OR @Partner IS NULL THROW 57020,N'c111 Memo fixture prerequisites are missing.',1;
IF NOT EXISTS(SELECT 1 FROM dbo.TDADCompanyProject WHERE ProjectID=@Project AND PartnerID=@Partner AND CompanyID=@Company) INSERT dbo.TDADCompanyProject(ProjectID,PartnerID,CompanyID,IsEnabled,IsTrial,CreateDate,CreatedBy) VALUES(@Project,@Partner,@Company,1,0,SYSUTCDATETIME(),@User); ELSE UPDATE dbo.TDADCompanyProject SET IsEnabled=1,ExpireDate=NULL,UpdateDate=SYSUTCDATETIME(),UpdatedBy=@User WHERE ProjectID=@Project AND PartnerID=@Partner AND CompanyID=@Company;
DECLARE @Users TABLE(UserID bigint);INSERT @Users VALUES(@User),(@Approver);
INSERT dbo.TDADUserProject(CompanyID,UserID,ProjectID,IsDefault,IsActive,CreateDate,CreateBy) SELECT @Company,u.UserID,@Project,0,1,SYSUTCDATETIME(),@User FROM @Users u WHERE NOT EXISTS(SELECT 1 FROM dbo.TDADUserProject x WHERE x.CompanyID=@Company AND x.UserID=u.UserID AND x.ProjectID=@Project);
UPDATE x SET IsActive=1,UpdateDate=SYSUTCDATETIME(),UpdateBy=@User FROM dbo.TDADUserProject x JOIN @Users u ON u.UserID=x.UserID WHERE x.CompanyID=@Company AND x.ProjectID=@Project;
INSERT dbo.TDADUserPermission(UserID,ProjectID,PermissionID,IsAllowed,IsActive,Remark,CreatedBy) SELECT u.UserID,@Project,p.PermissionID,1,1,@Run,@User FROM @Users u CROSS JOIN dbo.TDADPermission p WHERE p.ProjectID=@Project AND p.IsActive=1 AND NOT EXISTS(SELECT 1 FROM dbo.TDADUserPermission x WHERE x.UserID=u.UserID AND x.ProjectID=@Project AND x.PermissionID=p.PermissionID);
UPDATE up SET IsAllowed=1,IsActive=1,ModifiedDate=SYSUTCDATETIME(),ModifiedBy=@User FROM dbo.TDADUserPermission up JOIN @Users u ON u.UserID=up.UserID JOIN dbo.TDADPermission p ON p.ProjectID=up.ProjectID AND p.PermissionID=up.PermissionID WHERE up.ProjectID=@Project AND p.IsActive=1;
IF NOT EXISTS(SELECT 1 FROM dbo.TDMESystemSetting WHERE CompanyID=@Company) INSERT dbo.TDMESystemSetting(CompanyID,MaxAttachmentMB,AllowedExtensions,AutoDistribute,CreateBy) VALUES(@Company,20,N'pdf,doc,docx,xls,xlsx,ppt,pptx,jpg,jpeg,png',1,@User);
IF NOT EXISTS(SELECT 1 FROM dbo.TDMEApprovalRoute WHERE CompanyID=@Company AND RouteCode=N'MEMO-STD') INSERT dbo.TDMEApprovalRoute(CompanyID,RouteCode,RouteName,CreateBy) VALUES(@Company,N'MEMO-STD',N'สายอนุมัติมาตรฐาน 1 ขั้น',@User);
DECLARE @Route bigint=(SELECT RouteID FROM dbo.TDMEApprovalRoute WHERE CompanyID=@Company AND RouteCode=N'MEMO-STD');
IF NOT EXISTS(SELECT 1 FROM dbo.TDMEApprovalRouteStep WHERE CompanyID=@Company AND RouteID=@Route) INSERT dbo.TDMEApprovalRouteStep(CompanyID,RouteID,StepOrder,AssigneeUserID,StepName,CreateBy) VALUES(@Company,@Route,1,@Approver,N'ผู้อนุมัติ Memo',@User);
IF NOT EXISTS(SELECT 1 FROM dbo.TDMETemplate WHERE CompanyID=@Company AND TemplateCode=N'GENERAL') INSERT dbo.TDMETemplate(CompanyID,TemplateCode,TemplateName,SubjectDefault,BodyDeltaJson,BodyPlainText,CreateBy) VALUES(@Company,N'GENERAL',N'Memo ทั่วไป',N'ขออนุมัติดำเนินการ',N'[{"insert":"เรียน ผู้เกี่ยวข้อง\n\nรายละเอียด\n"}]',N'เรียน ผู้เกี่ยวข้อง

รายละเอียด',@User);
DECLARE @Template bigint=(SELECT TemplateID FROM dbo.TDMETemplate WHERE CompanyID=@Company AND TemplateCode=N'GENERAL');
IF NOT EXISTS(SELECT 1 FROM dbo.TDMEType WHERE CompanyID=@Company AND TypeCode=N'GENERAL') INSERT dbo.TDMEType(CompanyID,TypeCode,TypeName,NumberPrefix,DefaultRouteID,DefaultTemplateID,DefaultConfidentiality,CreateBy) VALUES(@Company,N'GENERAL',N'Memo ทั่วไป',N'MEMO',@Route,@Template,N'INTERNAL',@User);
DECLARE @Type bigint=(SELECT MemoTypeID FROM dbo.TDMEType WHERE CompanyID=@Company AND TypeCode=N'GENERAL');
DECLARE @Cases TABLE(Suffix nvarchar(20),Subject nvarchar(500),Status nvarchar(30));INSERT @Cases VALUES(N'DRAFT',N'ข้อมูลตัวอย่าง Memo สถานะร่าง',N'DRAFT'),(N'APPROVAL',N'ข้อมูลตัวอย่าง Memo รออนุมัติ',N'IN_APPROVAL'),(N'RETURNED',N'ข้อมูลตัวอย่าง Memo ส่งกลับแก้ไข',N'RETURNED'),(N'DISTRIBUTED',N'ข้อมูลตัวอย่าง Memo แจกจ่ายแล้ว',N'DISTRIBUTED');
DECLARE @Suffix nvarchar(20),@Subject nvarchar(500),@Status nvarchar(30);DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT Suffix,Subject,Status FROM @Cases;OPEN c;FETCH NEXT FROM c INTO @Suffix,@Subject,@Status;WHILE @@FETCH_STATUS=0 BEGIN
 DECLARE @Temp nvarchar(80)=@Run+N'-'+@Suffix;DECLARE @Memo bigint=(SELECT MemoID FROM dbo.TDMEMemo WHERE CompanyID=@Company AND TemporaryNo=@Temp);
 IF @Memo IS NULL BEGIN INSERT dbo.TDMEMemo(CompanyID,MemoTypeID,TemporaryNo,MemoNo,SubjectText,ToText,MemoDate,OwnerUserID,OwnerDepartmentID,ConfidentialityCode,StatusCode,ApprovedAt,DistributedAt,CreateBy) VALUES(@Company,@Type,@Temp,CASE WHEN @Status=N'DISTRIBUTED' THEN N'MEMO-2026-TEST01' END,@Subject,N'พนักงานที่เกี่ยวข้อง',CONVERT(date,SYSUTCDATETIME()),@User,@Department,N'INTERNAL',@Status,CASE WHEN @Status=N'DISTRIBUTED' THEN SYSUTCDATETIME() END,CASE WHEN @Status=N'DISTRIBUTED' THEN SYSUTCDATETIME() END,@User);SET @Memo=SCOPE_IDENTITY();INSERT dbo.TDMEMemoVersion(CompanyID,MemoID,VersionNo,BodyDeltaJson,BodyPlainText,IsLocked,SubmittedAt,CreateBy) VALUES(@Company,@Memo,1,N'[{"insert":"เนื้อหาตัวอย่างสำหรับทดสอบ Flow Memo ภาษาไทย\n"}]',N'เนื้อหาตัวอย่างสำหรับทดสอบ Flow Memo ภาษาไทย',CASE WHEN @Status=N'DISTRIBUTED' THEN 1 ELSE 0 END,CASE WHEN @Status<>N'DRAFT' THEN SYSUTCDATETIME() END,@User);DECLARE @Version bigint=SCOPE_IDENTITY();UPDATE dbo.TDMEMemo SET CurrentVersionID=@Version WHERE MemoID=@Memo;INSERT dbo.TDMEMemoRecipient(CompanyID,MemoID,VersionID,RecipientRole,SubjectType,SubjectID,CreateBy) VALUES(@Company,@Memo,@Version,N'TO',N'USER',@Approver,@User);IF @Status=N'IN_APPROVAL' INSERT dbo.TDMEMemoApproval(CompanyID,MemoID,VersionID,StepOrder,StepName,AssigneeUserID,StatusCode) VALUES(@Company,@Memo,@Version,1,N'ผู้อนุมัติ Memo',@Approver,N'PENDING');IF @Status=N'RETURNED' INSERT dbo.TDMEMemoApproval(CompanyID,MemoID,VersionID,StepOrder,StepName,AssigneeUserID,StatusCode,DecisionBy,DecisionAt,DecisionNote) VALUES(@Company,@Memo,@Version,1,N'ผู้อนุมัติ Memo',@Approver,N'RETURNED',@Approver,SYSUTCDATETIME(),N'กรุณาแก้ไขรายละเอียด');IF @Status=N'DISTRIBUTED' INSERT dbo.TDMEMemoApproval(CompanyID,MemoID,VersionID,StepOrder,StepName,AssigneeUserID,StatusCode,DecisionBy,DecisionAt) VALUES(@Company,@Memo,@Version,1,N'ผู้อนุมัติ Memo',@Approver,N'APPROVED',@Approver,SYSUTCDATETIME());INSERT dbo.TDMEAudit(CompanyID,MemoID,VersionID,ActionCode,DetailText,UserID) VALUES(@Company,@Memo,@Version,N'FIXTURE',@Run,@User);END
 FETCH NEXT FROM c INTO @Suffix,@Subject,@Status;END CLOSE c;DEALLOCATE c;
COMMIT;
